import{_ as i,o as a,c as t,a0 as n}from"./chunks/framework.bcCluOOn.js";const d=JSON.parse('{"title":"AAYU Language Specification","description":"","frontmatter":{},"headers":[],"relativePath":"specification/index.md","filePath":"specification/index.md"}'),o={name:"specification/index.md"};function l(s,e,r,c,p,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="aayu-language-specification" tabindex="-1">AAYU Language Specification <a class="header-anchor" href="#aayu-language-specification" aria-label="Permalink to &quot;AAYU Language Specification&quot;">​</a></h1><p>Welcome to the official specification for <strong>AAYU</strong>, the architecture-first language used by the AAYU Software Factory.</p><p>This document formally defines the lexical structure, grammar, built-in types, compilation pipeline, intermediate representation, target engine, and experimental runtime path.</p><h2 id="design-philosophy" tabindex="-1">Design Philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to &quot;Design Philosophy&quot;">​</a></h2><p>AAYU is designed with a singular focus: <strong>bridging the gap between human intent and machine execution.</strong></p><p>Traditional programming requires developers to translate business requirements into deeply technical implementation details. AAYU allows developers or intent engines to write architectural declarations like <code>entity</code>, <code>workflow</code>, and <code>page</code>, which the compiler turns into generated software.</p><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/INTENT-TO-SILICON/specification/syntax.html">Syntax Basics</a></li><li><a href="/INTENT-TO-SILICON/specification/types.html">Data Types</a></li><li><a href="/INTENT-TO-SILICON/specification/entities.html">Entities &amp; Data Models</a></li><li><a href="/INTENT-TO-SILICON/specification/relations.html">Relations</a></li><li><a href="/INTENT-TO-SILICON/specification/pages.html">UI DSL (Pages &amp; Components)</a></li><li><a href="/INTENT-TO-SILICON/specification/workflows.html">Workflows &amp; State Machines</a></li><li><a href="/INTENT-TO-SILICON/specification/modules.html">Modularity &amp; Packages</a></li><li><a href="/INTENT-TO-SILICON/specification/compiler.html">Compiler &amp; IR</a></li><li><a href="/INTENT-TO-SILICON/specification/runtime.html">Runtime Environment</a></li><li><a href="/INTENT-TO-SILICON/specification/stdlib.html">Standard Library</a></li></ul>',8)])])}const m=i(o,[["render",l]]);export{d as __pageData,m as default};
